actions.script:
const givenNum = mergeRequestNum
mergeRequestId = null
mergeRequestNum = null
const me = ec.user.userId
if (!me) { ec.message.addError(ec.l10n.localize('Sign in to open a merge request')); return }
const pushed = !!pushedForReview
if ((pushed || headCommitId || reviewTopic || hidden || givenNum != null) && !ec.artifactExecution.authzDisabled()) {
    ec.message.addError('mergeRequestNum, pushedForReview, headCommitId, reviewTopic and hidden are given only with authorization disabled'); return }
if (!access.canView) { ec.message.addError(ec.resource.expand('Repository ${repositoryId} not found', '', {repositoryId})); return }
if (access.archived) { ec.message.addError('GitArchived: ' + ec.resource.expand('Repository ${repositoryId} is archived', '', {repositoryId})); return }
const short = (name) => String(name || '').trim().replace(/^refs\/heads\//, '')
const repo = ec.entity.find('moqui.resource.GitRepository').condition('repositoryId', repositoryId).disableAuthz().one()
const target = short(targetRef) || (repo.branch || 'main')
const sourceRepoId = !pushed && sourceRepositoryId && String(sourceRepositoryId) !== String(repositoryId) ? String(sourceRepositoryId) : null
const source = pushed ? null : short(sourceRef)
if (pushed) {
    if (!headCommitId) { ec.message.addError('headCommitId is required for a merge request pushed for review'); return }
} else if (!source) {
    ec.message.addError('sourceRef is required'); return
} else if (sourceRepoId) {
    // from a fork: the author reads both, and the two share a fork network (and so their objects)
    const sourceRepo = ec.entity.find('moqui.resource.GitRepository').condition('repositoryId', sourceRepoId).disableAuthz().one()
    const sourceAccess = ec.service.sync().name('org.moqui.git.GitServices.get#GitRepositoryAccess').parameters({repositoryId: sourceRepoId}).call()
    if (!sourceRepo || !sourceAccess || !sourceAccess.canView) {
        ec.message.addError(ec.resource.expand('Repository ${repositoryId} not found', '', {repositoryId: sourceRepoId})); return }
    // its branch is followed from then on, so only who may write there offers it
    if (!sourceAccess.canUpdate) { ec.message.addError(ec.resource.expand('You may not push to ${repositoryId}', '', {repositoryId: sourceRepoId})); return }
    if (!repo.forkNetworkId || sourceRepo.forkNetworkId !== repo.forkNetworkId) {
        ec.message.addError('GitNotInNetwork: ' + sourceRepoId + ' and ' + repositoryId + ' are not forks of one repository'); return }
} else {
    if (!access.canCreate && !access.canUpdate) { ec.message.addError(ec.resource.expand('You may not push to ${repositoryId}', '', {repositoryId})); return }
    if (source === target) { ec.message.addError(ec.l10n.localize('The source and the target are the same branch')); return }
}
const branchesOf = (id) => {
    const refs = ec.service.sync().name('org.moqui.git.GitServices.get#GitRefs').parameters({repositoryId: id, refType: 'branch'}).call()
    return Array.from((refs && refs.refList) || []).map((ref) => ref.shortName)
}
const targetBranches = branchesOf(repositoryId)
if (!targetBranches.includes(target)) {
    ec.message.addError('GitNoSuchRef: ' + ec.resource.expand('No branch ${branch} in ${repositoryId}', '', {branch: target, repositoryId})); return }
if (!pushed) {
    const sourceBranches = sourceRepoId ? branchesOf(sourceRepoId) : targetBranches
    if (!sourceBranches.includes(source)) {
        ec.message.addError('GitNoSuchRef: ' + ec.resource.expand('No branch ${branch} in ${repositoryId}', '', {branch: source, repositoryId: sourceRepoId || repositoryId})); return }
    const existing = Array.from(ec.entity.find('moqui.resource.GitMergeRequest').condition({repositoryId, sourceRef: source, targetRef: target})
            .condition('statusId', 'in', ['GmrDraft', 'GmrOpen']).disableAuthz().list())
            .filter((row) => (row.sourceRepositoryId || null) === sourceRepoId && row.pushedForReview !== 'Y')
    if (existing.length > 0) { ec.message.addError('GitMergeRequestExists: Merge request !' + existing[0].mergeRequestNum + ' is already open for ' + source + ' into ' + target); return }
}
if (mergeMethodEnumId && !['GmmMerge', 'GmmSquash', 'GmmFastForward', 'GmmRebase'].includes(mergeMethodEnumId)) {
    ec.message.addError(mergeMethodEnumId + ' is not a merge method'); return }
const reviewers = Array.from(new Set(Array.from(reviewerUserIdList || []).map(String).filter((id) => id && id !== me)))
for (const reviewer of reviewers) {
    // a reviewer reads the merge request's commits: refuse one who may not view the repository
    const reviewerAccess = ec.service.sync().name('org.moqui.git.GitServices.get#GitRepositoryAccess')
        .parameters({repositoryId, userId: reviewer}).disableAuthz().call()
    if (!reviewerAccess || !reviewerAccess.canView) {
        ec.message.addError('User ' + reviewer + ' may not view repository ' + repositoryId + ', so may not review in it'); return }
}
let num
if (givenNum != null) {
    num = Number(givenNum)
    if (!Number.isInteger(num) || num < 1) { ec.message.addError('mergeRequestNum is a whole number from 1'); return }
    const taken = ec.entity.find('moqui.resource.GitMergeRequest').condition({repositoryId, mergeRequestNum: num}).disableAuthz().count()
    if (taken > 0) { ec.message.addError('GitNumberTaken: Merge request !' + num + ' is there already in ' + repositoryId); return }
} else {
    const last = ec.entity.find('moqui.resource.GitMergeRequest').condition('repositoryId', repositoryId)
            .orderBy('-mergeRequestNum').limit(1).selectField('mergeRequestNum').disableAuthz().list()
    num = (last.size() > 0 ? Number(last.get(0).mergeRequestNum || 0) : 0) + 1
}
const headRef = 'refs/merge-requests/' + num + '/head'
const now = ec.user.nowTimestamp
const mr = ec.entity.makeValue('moqui.resource.GitMergeRequest')
mr.setSequencedIdPrimary()
mr.setFields({repositoryId, mergeRequestNum: num, title: String(title).trim(), description: description || null,
    sourceRef: pushed ? headRef : source, sourceRepositoryId: sourceRepoId, pushedForReview: pushed ? 'Y' : 'N',
    reviewTopic: pushed && reviewTopic ? String(reviewTopic) : null,
    targetRef: target, statusId: draft ? 'GmrDraft' : 'GmrOpen', authorUserId: me,
    createdDate: now, lastUpdatedDate: now, mergeableEnumId: 'GmaUnchecked', hiddenDate: hidden ? now : null,
    mergeMethodEnumId: mergeMethodEnumId || null, deleteSourceBranch: deleteSourceBranch && !pushed ? 'Y' : 'N'}, true, null, null)
mr.create()
// a repository that has held a hidden merge request reads commits by id through its refs only, from then on
const noteHidden = () => ec.entity.find('moqui.resource.GitRepository').condition('repositoryId', repositoryId)
        .condition('reviewHiddenDate', null).disableAuthz().updateAll({reviewHiddenDate: now})
if (hidden) noteHidden()
// the head's own ref, with the objects of a fork brought to this repository; then what it changes
const synced = ec.service.sync().name('org.moqui.git.GitReviewServices.sync#MergeRequestHead')
        .parameters({mergeRequestId: mr.mergeRequestId, headCommitId: pushed ? headCommitId : null}).disableAuthz().call()
if (ec.message.hasError()) return
// one from a fork, as one pushed for review, starts hidden where the server says so (review-start-hidden)
const startHidden = !!hidden || !!(synced && synced.startHidden)
if (startHidden && !mr.hiddenDate) { mr.hiddenDate = now; mr.update(); noteHidden() }
let compare = ec.service.sync().name('org.moqui.git.GitServices.get#GitCompare')
        .parameters({repositoryId, base: 'refs/heads/' + target, head: headRef, checkMergeable: true, includeHidden: startHidden})
if (startHidden) compare = compare.disableAuthz()
const checked = compare.call()
if (ec.message.hasError()) return
if (!checked || !checked.headCommitId) { ec.message.addError('The source of the merge request names no commit'); return }
mr.setFields({headCommitId: checked.headCommitId, baseCommitId: checked.mergeBaseId || null,
    mergeableEnumId: checked.alreadyMerged ? 'GmaMerged' : (checked.mergeable ? 'GmaMergeable' : 'GmaConflict'),
    conflictPaths: Array.from(checked.conflictPaths || []).join('\n') || null}, true, null, null)
mr.update()
mergeRequestId = mr.mergeRequestId
mergeRequestNum = num
for (const reviewer of reviewers) {
    const row = ec.entity.makeValue('moqui.resource.GitMergeRequestReviewer')
    row.setFields({mergeRequestId, userId: reviewer, statusId: 'GmrrRequested', requestedDate: now}, true, null, null)
    row.create()
}
ec.service.sync().name('org.moqui.git.GitReviewServices.queue#MergeRequestEvent').parameters({mergeRequestId, action: 'opened'}).disableAuthz().call()

const namedId = mergeRequestId
mergeRequestId = null
mergeRequestNum = null
created = false
if (!ec.artifactExecution.authzDisabled()) { ec.message.addError('propose#MergeRequest is called by the git server and commit#GitFiles only'); return }
const me = ec.user.userId
if (!me) { ec.message.addError(ec.l10n.localize('Sign in to open a merge request')); return }
const open = ['GmrDraft', 'GmrOpen']
const target = String(targetRef || '').trim().replace(/^refs\/heads\//, '')
const reviewTopic = topic ? String(topic).trim().substring(0, 60) || null : null
// a title is plain text: a commit summary may hold angle brackets, which a title parameter refuses
const plain = (text) => String(text || '').replace(/[<>]/g, '').trim().substring(0, 250)
let mr = null
if (namedId) {
    mr = ec.entity.find('moqui.resource.GitMergeRequest').condition('mergeRequestId', namedId).disableAuthz().one()
    if (!mr || mr.repositoryId !== repositoryId || mr.pushedForReview !== 'Y' || mr.authorUserId !== me
            || !open.includes(mr.statusId) || mr.targetRef !== target) {
        ec.message.addError('Merge request ' + namedId + ' is not an open proposal of yours for ' + target); return }
} else {
    const rows = Array.from(ec.entity.find('moqui.resource.GitMergeRequest')
            .condition({repositoryId, authorUserId: me, targetRef: target, pushedForReview: 'Y'})
            .condition('statusId', 'in', open).orderBy('-mergeRequestNum').disableAuthz().list())
    mr = rows.find((row) => (row.reviewTopic || null) === reviewTopic) || null
}
if (mr) {
    ec.service.sync().name('org.moqui.git.GitReviewServices.sync#MergeRequestHead')
            .parameters({mergeRequestId: mr.mergeRequestId, headCommitId}).disableAuthz().call()
    if (ec.message.hasError()) return
    const fields = {}
    if (title && plain(title)) fields.title = plain(title)
    if (description) fields.description = description
    if (Object.keys(fields).length) { mr.setFields(fields, true, null, null); mr.update() }
    ec.service.sync().name('org.moqui.git.GitReviewServices.sync#MergeRequest').parameters({mergeRequestId: mr.mergeRequestId}).call()
    if (ec.message.hasError()) return
    mergeRequestId = mr.mergeRequestId
    mergeRequestNum = mr.mergeRequestNum
    return
}
const made = ec.service.sync().name('org.moqui.git.GitReviewServices.create#MergeRequest').parameters({repositoryId, targetRef: target,
    title: plain(title) || plain(defaultTitle) || ('Changes for ' + target), description: description || defaultDescription || null,
    draft: !!draft, pushedForReview: true, headCommitId, reviewTopic, hidden: !!hidden}).disableAuthz().call()
if (ec.message.hasError() || !made || !made.mergeRequestId) return
mergeRequestId = made.mergeRequestId
mergeRequestNum = made.mergeRequestNum
created = true

const mr = ec.entity.find('moqui.resource.GitMergeRequest').condition('mergeRequestId', mergeRequestId).disableAuthz().one()
if (!mr) { ec.message.addError('No merge request ' + mergeRequestId); return }
const access = ec.service.sync().name('org.moqui.git.GitServices.get#GitRepositoryAccess').parameters({repositoryId: mr.repositoryId}).call()
if (!access.canView) { ec.message.addError('No merge request ' + mergeRequestId); return }
// a hidden one is the application's to show: it asks with authorization disabled
if (mr.hiddenDate && !ec.artifactExecution.authzDisabled()) { ec.message.addError('No merge request ' + mergeRequestId); return }
if (!['GmrDraft', 'GmrOpen'].includes(mr.statusId)) {
    // one from before the head refs were kept gets its ref from its recorded head, so its commits and checks are read
    ec.service.sync().name('org.moqui.git.GitReviewServices.sync#MergeRequestHead').parameters({mergeRequestId}).disableAuthz().call()
    if (ec.message.hasError()) ec.message.clearErrors()
}
const repo = ec.entity.find('moqui.resource.GitRepository').condition('repositoryId', mr.repositoryId).disableAuthz().one()
const nameOf = (userId) => {
    const account = userId ? ec.entity.find('moqui.security.UserAccount').condition('userId', userId).useCache(true).disableAuthz().one() : null
    return account ? (account.userFullName || account.username || userId) : userId
}
mergeRequest = Object.assign({}, mr.getMap(), {authorName: nameOf(mr.authorUserId),
    mergedByName: nameOf(mr.mergedByUserId), conflictPathList: String(mr.conflictPaths || '').split('\n').filter((path) => path)})
const rules = ec.service.sync().name('org.moqui.git.GitServices.get#GitBranchRules')
        .parameters({repositoryId: mr.repositoryId, refName: mr.targetRef}).call()
branchRules = rules
const head = mr.headCommitId
// only the approvals of users who may push count toward the branch rules (a viewer's review is a comment)
const approvals = ec.service.sync().name('org.moqui.git.GitReviewServices.get#MergeRequestApprovals')
        .parameters({mergeRequestId}).call() || {}
const counted = Array.from(approvals.approverUserIdList || []).map(String)
approvalCount = counted.length
reviewerList = []
for (const reviewer of Array.from(ec.entity.find('moqui.resource.GitMergeRequestReviewer').condition('mergeRequestId', mergeRequestId)
        .orderBy('requestedDate').disableAuthz().list())) {
    const current = reviewer.reviewedCommitId != null && reviewer.reviewedCommitId === head
    reviewerList.push({userId: reviewer.userId, name: nameOf(reviewer.userId), statusId: reviewer.statusId,
        requestedDate: reviewer.requestedDate, reviewedDate: reviewer.reviewedDate, reviewedCommitId: reviewer.reviewedCommitId,
        reviewNote: reviewer.reviewNote, ofCurrentHead: current, approvalCounts: counted.includes(String(reviewer.userId))})
}
// a hidden head's checks are read as the merge request is: by the application
let statuses = ec.service.sync().name('org.moqui.git.GitServices.get#GitCommitStatuses')
        .parameters({repositoryId: mr.repositoryId, commitId: head, includeHidden: !!mr.hiddenDate})
if (mr.hiddenDate) statuses = statuses.disableAuthz()
const checks = head ? statuses.call() : {}
checkState = checks.state || null
checkList = Array.from(checks.statusList || [])
mergeMethodEnumId = mr.mergeMethodEnumId || repo.defaultMergeMethodEnumId || 'GmmMerge'
missingList = []
if (mr.statusId === 'GmrDraft') missingList.push('It is a draft: mark it ready')
else if (mr.statusId !== 'GmrOpen') missingList.push('It is not open')
if (repo.archivedDate) missingList.push('The repository is archived')
if (mr.mergeableEnumId === 'GmaConflict') missingList.push('Conflicts in ' + mergeRequest.conflictPathList.join(', '))
if (mr.mergeableEnumId === 'GmaUnchecked') missingList.push('The target moved; checking')
const required = Number(rules.requiredApprovals || 0)
if (approvalCount < required) missingList.push(approvalCount + ' of ' + required + ' approvals')
const passed = checkList.filter((check) => check.state === 'success').map((check) => check.context)
const failing = Array.from(rules.requiredStatusContexts || []).filter((context) => !passed.includes(context))
if (failing.length) missingList.push('Checks not passed: ' + failing.join(', '))
const allowed = Array.from(rules.allowedMergeMethods || [])
if (allowed.length && !allowed.includes(mergeMethodEnumId)) missingList.push('The branch rules allow ' + allowed.join(', '))
canEdit = !!ec.user.userId && (ec.user.userId === mr.authorUserId || access.canUpdate) && ['GmrDraft', 'GmrOpen'].includes(mr.statusId)
if (mr.hiddenDate) missingList.push('It is hidden')
canMerge = !!access.canUpdate && missingList.length === 0
if (!access.canUpdate) missingList.push('You may not push to the target')

const mr = ec.entity.find('moqui.resource.GitMergeRequest').condition('mergeRequestId', mergeRequestId).disableAuthz().one()
if (!mr) { ec.message.addError('No merge request ' + mergeRequestId); return }
const access = ec.service.sync().name('org.moqui.git.GitServices.get#GitRepositoryAccess').parameters({repositoryId: mr.repositoryId}).call()
if (!access.canView) { ec.message.addError('No merge request ' + mergeRequestId); return }
// a hidden one is its author's and the application's: to anyone else there is none
if (mr.hiddenDate && !ec.artifactExecution.authzDisabled() && ec.user.userId !== mr.authorUserId) { ec.message.addError('No merge request ' + mergeRequestId); return }
if (ec.user.userId !== mr.authorUserId && !access.canUpdate) { ec.message.addError(ec.l10n.localize('Only its author or a maintainer changes a merge request')); return }
if (!['GmrDraft', 'GmrOpen'].includes(mr.statusId)) { ec.message.addError(ec.l10n.localize('A merged or closed merge request does not change')); return }
const fields = {}
if (title != null && String(title).trim()) fields.title = String(title).trim()
if (description != null) fields.description = description || null
if (draft != null) fields.statusId = draft ? 'GmrDraft' : 'GmrOpen'
if (deleteSourceBranch != null) fields.deleteSourceBranch = deleteSourceBranch ? 'Y' : 'N'
if (mergeMethodEnumId != null) {
    if (mergeMethodEnumId && !['GmmMerge', 'GmmSquash', 'GmmFastForward', 'GmmRebase'].includes(mergeMethodEnumId)) {
        ec.message.addError(mergeMethodEnumId + ' is not a merge method'); return }
    fields.mergeMethodEnumId = mergeMethodEnumId || null
}
const target = targetRef ? String(targetRef).trim().replace(/^refs\/heads\//, '') : null
if (target && target !== mr.targetRef) {
    if (target === mr.sourceRef) { ec.message.addError(ec.l10n.localize('The source and the target are the same branch')); return }
    // a branch that is there, as create#MergeRequest asks
    const refs = ec.service.sync().name('org.moqui.git.GitServices.get#GitRefs').parameters({repositoryId: mr.repositoryId, refType: 'branch'}).call()
    if (!Array.from((refs && refs.refList) || []).some((ref) => ref.shortName === target)) {
        ec.message.addError('GitNoSuchRef: ' + ec.resource.expand('No branch ${branch} in ${repositoryId}', '', {branch: target, repositoryId: mr.repositoryId})); return }
    fields.targetRef = target
}
if (!Object.keys(fields).length) return
fields.lastUpdatedDate = ec.user.nowTimestamp
mr.setFields(fields, true, null, null)
mr.update()
if (fields.targetRef) {
    ec.service.sync().name('org.moqui.git.GitReviewServices.check#MergeRequest').parameters({mergeRequestId}).call()
}
ec.service.sync().name('org.moqui.git.GitReviewServices.queue#MergeRequestEvent').parameters({mergeRequestId,
    action: fields.statusId === 'GmrOpen' && mr.statusId === 'GmrOpen' && draft === false ? 'ready' : 'updated'}).disableAuthz().call()

reviewerUserIdList = []
const mr = ec.entity.find('moqui.resource.GitMergeRequest').condition('mergeRequestId', mergeRequestId).disableAuthz().one()
if (!mr) { ec.message.addError('No merge request ' + mergeRequestId); return }
const access = ec.service.sync().name('org.moqui.git.GitServices.get#GitRepositoryAccess').parameters({repositoryId: mr.repositoryId}).call()
if (!access.canView) { ec.message.addError('No merge request ' + mergeRequestId); return }
// a hidden one is its author's and the application's: to anyone else there is none
if (mr.hiddenDate && !ec.artifactExecution.authzDisabled() && ec.user.userId !== mr.authorUserId) { ec.message.addError('No merge request ' + mergeRequestId); return }
if (ec.user.userId !== mr.authorUserId && !access.canUpdate) { ec.message.addError(ec.l10n.localize('Only its author or a maintainer sets the reviewers')); return }
const ids = (list) => Array.from(list || []).map(String).filter((id) => id && id !== mr.authorUserId)
const rows = Array.from(ec.entity.find('moqui.resource.GitMergeRequestReviewer').condition('mergeRequestId', mergeRequestId).disableAuthz().list())
const current = rows.map((row) => row.userId)
let wanted = userIdList != null ? ids(userIdList) : current.concat(ids(addUserIdList))
const removed = ids(removeUserIdList)
wanted = Array.from(new Set(wanted)).filter((id) => !removed.includes(id))
const added = wanted.filter((id) => !current.includes(id))
for (const userId of added) {
    const account = ec.entity.find('moqui.security.UserAccount').condition('userId', userId).disableAuthz().one()
    if (!account) { ec.message.addError('No user ' + userId); return }
    // a reviewer reads the merge request's commits: refuse one who may not view the repository
    const reviewerAccess = ec.service.sync().name('org.moqui.git.GitServices.get#GitRepositoryAccess')
        .parameters({repositoryId: mr.repositoryId, userId}).disableAuthz().call()
    if (!reviewerAccess || !reviewerAccess.canView) {
        ec.message.addError('User ' + userId + ' may not view repository ' + mr.repositoryId + ', so may not review merge request ' + mergeRequestId)
        return
    }
}
for (const row of rows) { if (!wanted.includes(row.userId)) row.delete() }
for (const userId of added) {
    const row = ec.entity.makeValue('moqui.resource.GitMergeRequestReviewer')
    row.setFields({mergeRequestId, userId, statusId: 'GmrrRequested', requestedDate: ec.user.nowTimestamp}, true, null, null)
    row.create()
}
mr.lastUpdatedDate = ec.user.nowTimestamp
mr.update()
reviewerUserIdList = wanted

const mr = ec.entity.find('moqui.resource.GitMergeRequest').condition('mergeRequestId', mergeRequestId).disableAuthz().one()
if (!mr) { ec.message.addError('No merge request ' + mergeRequestId); return }
const access = ec.service.sync().name('org.moqui.git.GitServices.get#GitRepositoryAccess').parameters({repositoryId: mr.repositoryId}).call()
const me = ec.user.userId
if (!me || !access.canView) { ec.message.addError('No merge request ' + mergeRequestId); return }
// a hidden one is its author's and the application's: to anyone else there is none
if (mr.hiddenDate && !ec.artifactExecution.authzDisabled() && ec.user.userId !== mr.authorUserId) { ec.message.addError('No merge request ' + mergeRequestId); return }
if (!['GmrDraft', 'GmrOpen'].includes(mr.statusId)) { ec.message.addError(ec.l10n.localize('A merged or closed merge request takes no review')); return }
statusId = {approve: 'GmrrApproved', request_changes: 'GmrrChangesRequested', comment: 'GmrrCommented'}[decision]
if (!statusId) { ec.message.addError(ec.l10n.localize('The decision is approve, request_changes or comment')); return }
if (statusId === 'GmrrApproved' && me === mr.authorUserId) { ec.message.addError(ec.l10n.localize('You do not approve your own merge request')); return }
if (statusId === 'GmrrApproved' && !access.canUpdate) {
    ec.message.addError(ec.l10n.localize('Approving needs the right to push to the repository: you may comment or request changes')); return }
let row = ec.entity.find('moqui.resource.GitMergeRequestReviewer').condition({mergeRequestId, userId: me}).disableAuthz().one()
const fields = {statusId, reviewedCommitId: mr.headCommitId, reviewedDate: ec.user.nowTimestamp, reviewNote: note || null}
if (row) {
    row.setFields(fields, true, null, null)
    row.update()
} else {
    row = ec.entity.makeValue('moqui.resource.GitMergeRequestReviewer')
    row.setFields(Object.assign({mergeRequestId, userId: me, requestedDate: ec.user.nowTimestamp}, fields), true, null, null)
    row.create()
}
mr.lastUpdatedDate = ec.user.nowTimestamp
mr.update()
ec.service.sync().name('org.moqui.git.GitReviewServices.queue#MergeRequestEvent').parameters({mergeRequestId, action: 'reviewed'}).disableAuthz().call()

const mr = ec.entity.find('moqui.resource.GitMergeRequest').condition('mergeRequestId', mergeRequestId).disableAuthz().one()
if (!mr) { ec.message.addError('No merge request ' + mergeRequestId); return }
const access = ec.service.sync().name('org.moqui.git.GitServices.get#GitRepositoryAccess').parameters({repositoryId: mr.repositoryId}).call()
if (!access.canView) { ec.message.addError('No merge request ' + mergeRequestId); return }
// a hidden one is its author's and the application's: to anyone else there is none
if (mr.hiddenDate && !ec.artifactExecution.authzDisabled() && ec.user.userId !== mr.authorUserId) { ec.message.addError('No merge request ' + mergeRequestId); return }
if (ec.user.userId !== mr.authorUserId && !access.canUpdate) { ec.message.addError(ec.l10n.localize('Only its author or a maintainer closes a merge request')); return }
if (mr.statusId === 'GmrClosed') return
if (mr.statusId === 'GmrMerged') { ec.message.addError(ec.l10n.localize('The merge request is merged')); return }
mr.setFields({statusId: 'GmrClosed', closedDate: ec.user.nowTimestamp, lastUpdatedDate: ec.user.nowTimestamp}, true, null, null)
mr.update()
ec.service.sync().name('org.moqui.git.GitReviewServices.queue#MergeRequestEvent').parameters({mergeRequestId, action: 'closed'}).disableAuthz().call()

const mr = ec.entity.find('moqui.resource.GitMergeRequest').condition('mergeRequestId', mergeRequestId).disableAuthz().one()
if (!mr) { ec.message.addError('No merge request ' + mergeRequestId); return }
const access = ec.service.sync().name('org.moqui.git.GitServices.get#GitRepositoryAccess').parameters({repositoryId: mr.repositoryId}).call()
if (!access.canView) { ec.message.addError('No merge request ' + mergeRequestId); return }
// a hidden one is its author's and the application's: to anyone else there is none
if (mr.hiddenDate && !ec.artifactExecution.authzDisabled() && ec.user.userId !== mr.authorUserId) { ec.message.addError('No merge request ' + mergeRequestId); return }
if (ec.user.userId !== mr.authorUserId && !access.canUpdate) { ec.message.addError(ec.l10n.localize('Only its author or a maintainer reopens a merge request')); return }
if (mr.statusId !== 'GmrClosed') { ec.message.addError(ec.l10n.localize('Only a closed merge request reopens')); return }
if (access.archived) { ec.message.addError(ec.l10n.localize('The repository is archived')); return }
const open = ec.entity.find('moqui.resource.GitMergeRequest').condition({repositoryId: mr.repositoryId, sourceRef: mr.sourceRef, targetRef: mr.targetRef})
        .condition('sourceRepositoryId', mr.sourceRepositoryId || null)
        .condition('statusId', 'in', ['GmrDraft', 'GmrOpen']).disableAuthz().count()
if (open > 0) { ec.message.addError('Another merge request of ' + mr.sourceRef + ' into ' + mr.targetRef + ' is open'); return }
mr.setFields({statusId: 'GmrOpen', closedDate: null, lastUpdatedDate: ec.user.nowTimestamp}, true, null, null)
mr.update()
ec.service.sync().name('org.moqui.git.GitReviewServices.check#MergeRequest').parameters({mergeRequestId}).call()
if (ec.message.hasError()) return
ec.service.sync().name('org.moqui.git.GitReviewServices.queue#MergeRequestEvent').parameters({mergeRequestId, action: 'reopened'}).disableAuthz().call()

mergeRequestList = []
mergeRequestListCount = 0
// without git hosting in the build there are no repositories to have merge requests
if (!ec.factory.hasFeature('git')) return
let wanted = Array.from(repositoryIdList || []).map(String)
if (repositoryId) wanted.push(String(repositoryId))
const repos = ec.service.sync().name('org.moqui.git.GitServices.find#GitRepositories')
        .parameters({repositoryIdList: wanted.length ? wanted : null, includeArchived: true, pageNoLimit: true}).call()
const visible = Array.from(repos.repositoryList || []).map((repo) => repo.repositoryId)
if (!visible.length) return
const cf = ec.entity.conditionFactory
const statuses = Array.from(statusIdList || []).map(String)
if (statusId) statuses.push(String(statusId))
const reviewerOf = (userId, waiting) => {
    let rows = ec.entity.find('moqui.resource.GitMergeRequestReviewer').condition('userId', userId).disableAuthz()
    if (waiting) rows = rows.condition('statusId', 'GmrrRequested')
    return Array.from(rows.selectField('mergeRequestId').list()).map((row) => row.mergeRequestId)
}
const reviewed = reviewerUserId ? reviewerOf(reviewerUserId, false).concat(['_NA_']) : null
const waiting = waitingForUserId ? reviewerOf(waitingForUserId, true).concat(['_NA_']) : null
// a find is used once: one for the count, one for the page
const makeFind = () => {
    let find = ec.entity.find('moqui.resource.GitMergeRequest').condition('repositoryId', 'in', visible).disableAuthz()
    if (statuses.length) find = find.condition('statusId', 'in', statuses)
    if (authorUserId) find = find.condition('authorUserId', authorUserId)
    if (targetRef) find = find.condition('targetRef', String(targetRef).replace(/^refs\/heads\//, ''))
    if (text) find = find.condition(cf.makeCondition('title', 'like', '%' + String(text) + '%').ignoreCase())
    if (reviewed) find = find.condition('mergeRequestId', 'in', reviewed)
    if (waiting) find = find.condition('mergeRequestId', 'in', waiting).condition('statusId', 'GmrOpen')
    if (!(includeHidden && ec.artifactExecution.authzDisabled())) find = find.condition('hiddenDate', null)
    if (sourceRepositoryId) find = find.condition('sourceRepositoryId', sourceRepositoryId)
    return find
}
mergeRequestListCount = makeFind().count()
const rows = Array.from(makeFind().orderBy('-lastUpdatedDate').orderBy('-mergeRequestId').offset(pageIndex * pageSize).limit(pageSize).list())
const names = {}
const nameOf = (userId) => {
    if (!userId) return null
    if (!(userId in names)) {
        const account = ec.entity.find('moqui.security.UserAccount').condition('userId', userId).useCache(true).disableAuthz().one()
        names[userId] = account ? (account.userFullName || account.username || userId) : userId
    }
    return names[userId]
}
// the combined check state of each head, a query per repository
const heads = {}
for (const row of rows) { if (row.headCommitId) (heads[row.repositoryId] = heads[row.repositoryId] || []).push(row.headCommitId) }
const states = {}
for (const repo of Object.keys(heads)) {
    // of the heads the caller reads: a hidden one's only for the application
    const withHidden = !!includeHidden && ec.artifactExecution.authzDisabled()
    let statuses = ec.service.sync().name('org.moqui.git.GitServices.get#GitCommitStatuses')
            .parameters({repositoryId: repo, commitIdList: heads[repo], includeHidden: withHidden})
    if (withHidden) statuses = statuses.disableAuthz()
    const out = statuses.call()
    states[repo] = out.stateByCommit || {}
}
for (const row of rows) {
    const reviewers = Array.from(ec.entity.find('moqui.resource.GitMergeRequestReviewer').condition('mergeRequestId', row.mergeRequestId)
            .disableAuthz().list()).map((reviewer) => ({userId: reviewer.userId, name: nameOf(reviewer.userId), statusId: reviewer.statusId}))
    mergeRequestList.push({mergeRequestId: row.mergeRequestId, repositoryId: row.repositoryId, mergeRequestNum: row.mergeRequestNum,
        title: row.title, sourceRef: row.sourceRef, targetRef: row.targetRef, statusId: row.statusId,
        sourceRepositoryId: row.sourceRepositoryId, pushedForReview: row.pushedForReview === 'Y', reviewTopic: row.reviewTopic,
        hiddenDate: row.hiddenDate,
        authorUserId: row.authorUserId, authorName: nameOf(row.authorUserId), createdDate: row.createdDate,
        lastUpdatedDate: row.lastUpdatedDate, headCommitId: row.headCommitId, mergeableEnumId: row.mergeableEnumId,
        checkState: row.headCommitId ? (states[row.repositoryId] || {})[row.headCommitId] || null : null, reviewerList: reviewers})
}

const mr = ec.entity.find('moqui.resource.GitMergeRequest').condition('mergeRequestId', mergeRequestId).disableAuthz().one()
if (!mr) { ec.message.addError('No merge request ' + mergeRequestId); return }
const internal = ec.artifactExecution.authzDisabled()
if (mr.hiddenDate && !internal) { ec.message.addError('No merge request ' + mergeRequestId); return }
const open = ['GmrDraft', 'GmrOpen'].includes(mr.statusId)
if (!open) {
    // one from before the head refs were kept gets its ref from its recorded head, so its commits are read
    ec.service.sync().name('org.moqui.git.GitReviewServices.sync#MergeRequestHead').parameters({mergeRequestId}).disableAuthz().call()
    if (ec.message.hasError()) ec.message.clearErrors()
}
// the head of one from a fork or pushed for review is its own ref; a branch's is the branch
const ownHead = mr.pushedForReview === 'Y' || !!mr.sourceRepositoryId
const sourceHead = ownHead ? 'refs/merge-requests/' + mr.mergeRequestNum + '/head' : 'refs/heads/' + mr.sourceRef
const base = open ? 'refs/heads/' + mr.targetRef : (mr.baseCommitId || 'refs/heads/' + mr.targetRef)
const head = open ? sourceHead : (mr.headCommitId || sourceHead)
let call = ec.service.sync().name('org.moqui.git.GitServices.get#GitCompare')
        .parameters({repositoryId: mr.repositoryId, base, head, withDiffs, includeHidden: !!mr.hiddenDate && internal})
if (internal) call = call.disableAuthz()
const compared = call.call() || {}
baseCommitId = compared.baseCommitId; headCommitId = compared.headCommitId; mergeBaseId = compared.mergeBaseId
aheadBy = compared.aheadBy; behindBy = compared.behindBy; commitList = compared.commitList
fileList = compared.fileList; insertions = compared.insertions; deletions = compared.deletions

const mr = ec.entity.find('moqui.resource.GitMergeRequest').condition('mergeRequestId', mergeRequestId).disableAuthz().one()
if (!mr || !['GmrDraft', 'GmrOpen'].includes(mr.statusId)) return
const ownHead = mr.pushedForReview === 'Y' || !!mr.sourceRepositoryId
const checked = ec.service.sync().name('org.moqui.git.GitServices.merge#GitRefs').parameters({repositoryId: mr.repositoryId,
    source: ownHead ? 'refs/merge-requests/' + mr.mergeRequestNum + '/head' : 'refs/heads/' + mr.sourceRef,
    target: mr.targetRef, checkOnly: true, includeHidden: true}).disableAuthz().call()
const now = ec.user.nowTimestamp
if (ec.message.hasError()) {
    // a branch is gone: nothing to merge until it is back
    ec.logger.log('info', 'Merge request ' + mergeRequestId + ' not checked: ' + ec.message.getErrorsString())
    ec.message.clearErrors()
    mr.setFields({mergeableEnumId: 'GmaUnchecked', conflictPaths: null, lastUpdatedDate: now}, true, null, null)
    mr.update()
    mergeableEnumId = 'GmaUnchecked'
    return
}
if (checked.alreadyMerged) {
    const target = ec.service.sync().name('org.moqui.git.GitServices.get#GitRefs').parameters({repositoryId: mr.repositoryId, refType: 'branch'}).disableAuthz().call()
    const targetRef = Array.from(target.refList || []).find((ref) => ref.shortName === mr.targetRef)
    mr.setFields({statusId: 'GmrMerged', mergeableEnumId: 'GmaMerged', conflictPaths: null, mergedDate: now, lastUpdatedDate: now,
        mergeCommitId: targetRef ? targetRef.commitId : null}, true, null, null)
    mr.update()
    mergeableEnumId = 'GmaMerged'
    ec.service.sync().name('org.moqui.git.GitReviewServices.queue#MergeRequestEvent').parameters({mergeRequestId, action: 'merged'}).disableAuthz().call()
    return
}
mergeableEnumId = checked.mergeable ? 'GmaMergeable' : 'GmaConflict'
mr.setFields({mergeableEnumId, conflictPaths: Array.from(checked.conflictPaths || []).join('\n') || null,
    baseCommitId: checked.baseCommitId || mr.baseCommitId, lastUpdatedDate: now}, true, null, null)
mr.update()

const mr = ec.entity.find('moqui.resource.GitMergeRequest').condition('mergeRequestId', mergeRequestId).disableAuthz().one()
if (!mr || !['GmrDraft', 'GmrOpen'].includes(mr.statusId)) return
const synced = ec.service.sync().name('org.moqui.git.GitReviewServices.sync#MergeRequestHead')
        .parameters({mergeRequestId}).disableAuthz().call()
if (ec.message.hasError()) return
const head = synced ? synced.headCommitId : null
if (head && mr.headCommitId !== head) {
    mr.setFields({headCommitId: head, lastUpdatedDate: ec.user.nowTimestamp}, true, null, null)
    mr.update()
    const rules = ec.service.sync().name('org.moqui.git.GitServices.get#GitBranchRules')
            .parameters({repositoryId: mr.repositoryId, refName: mr.targetRef}).disableAuthz().call()
    if (rules && rules.dismissStaleApprovals) {
        ec.entity.find('moqui.resource.GitMergeRequestReviewer').condition({mergeRequestId, statusId: 'GmrrApproved'})
                .disableAuthz().updateAll({statusId: 'GmrrRequested'})
    }
    ec.service.sync().name('org.moqui.git.GitReviewServices.queue#MergeRequestEvent')
            .parameters({mergeRequestId, action: 'synchronize'}).disableAuthz().call()
}
ec.service.sync().name('org.moqui.git.GitReviewServices.check#MergeRequest').parameters({mergeRequestId}).call()

if (!String(refName).startsWith('refs/heads/')) return
const branch = String(refName).substring('refs/heads/'.length)
const cf = ec.entity.conditionFactory
const open = ['GmrDraft', 'GmrOpen']
// of this repository: the branch is the target, or the source of one that names no other repository
const own = Array.from(ec.entity.find('moqui.resource.GitMergeRequest').condition('repositoryId', repositoryId)
        .condition('statusId', 'in', open)
        .condition(cf.makeCondition([cf.makeCondition('sourceRef', 'equals', branch), cf.makeCondition('targetRef', 'equals', branch)], 'or'))
        .disableAuthz().list())
        .filter((mr) => mr.targetRef === branch || (!mr.sourceRepositoryId && mr.pushedForReview !== 'Y'))
// of other repositories of the network: this repository's branch is their source
const forked = Array.from(ec.entity.find('moqui.resource.GitMergeRequest').condition({sourceRepositoryId: repositoryId, sourceRef: branch})
        .condition('statusId', 'in', open).disableAuthz().list())
for (const mr of own.concat(forked)) {
    // the branch's head now, not the event's newId: the events of each change run on their own job, so a
    // late event of an older change would set a merge request's head back to a commit its branch has left
    try {
        ec.service.sync().name('org.moqui.git.GitReviewServices.sync#MergeRequest').parameters({mergeRequestId: mr.mergeRequestId}).call()
    } catch (err) {
        ec.logger.log('error', 'Merge request ' + mr.mergeRequestId + ' not refreshed: ' + err)
    }
    if (ec.message.hasError()) {
        ec.logger.log('error', 'Merge request ' + mr.mergeRequestId + ' not refreshed: ' + ec.message.getErrorsString())
        ec.message.clearErrors()
    }
}

const mr = ec.entity.find('moqui.resource.GitMergeRequest').condition('mergeRequestId', mergeRequestId).disableAuthz().one()
if (!mr) return
if (!ec.artifactExecution.authzDisabled()) {
    const access = ec.service.sync().name('org.moqui.git.GitServices.get#GitRepositoryAccess').parameters({repositoryId: mr.repositoryId}).call()
    if (!access || !access.canView) { ec.message.addError('No merge request ' + mergeRequestId); return }
    if (!access.canUpdate) { ec.message.addError('You may not update in repository ' + mr.repositoryId); return }
}
// a hidden one's title, text and head go to no webhook: set#MergeRequestHidden sends opened when it is shown
if (mr.hiddenDate) return
const state = {GmrDraft: 'draft', GmrOpen: 'open', GmrMerged: 'merged', GmrClosed: 'closed'}[mr.statusId] || mr.statusId
const author = mr.authorUserId ? ec.entity.find('moqui.security.UserAccount').condition('userId', mr.authorUserId).useCache(true).disableAuthz().one() : null
try {
    ec.service.sync().name('org.moqui.git.GitServices.queue#GitWebhookEvent').parameters({repositoryId: mr.repositoryId,
        event: 'merge_request', action, payload: {merge_request: {id: mr.mergeRequestId, number: mr.mergeRequestNum, title: mr.title,
            description: mr.description, state, draft: mr.statusId === 'GmrDraft', source_branch: mr.sourceRef, target_branch: mr.targetRef,
            source_repository: mr.sourceRepositoryId || mr.repositoryId, pushed_for_review: mr.pushedForReview === 'Y',
            head_ref: 'refs/merge-requests/' + mr.mergeRequestNum + '/head',
            head_sha: mr.headCommitId, base_sha: mr.baseCommitId, merge_commit_sha: mr.mergeCommitId,
            author: author ? author.username : mr.authorUserId}}}).disableAuthz().call()
} catch (err) {
    ec.logger.log('error', 'Merge request ' + mergeRequestId + ' webhooks not queued: ' + err)
}
if (ec.message.hasError()) {
    ec.logger.log('error', 'Merge request ' + mergeRequestId + ' webhooks not queued: ' + ec.message.getErrorsString())
    ec.message.clearErrors()
}
